#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> pii;
char mazeX[15][15], mazeY[15][15];
int dirX[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int nodeMap[65][15][15];
int maxCap[15][15];
int nodeCount = 1;

struct Edge {
  int u, v;
  long long cap, flow;
  Edge() {}
  Edge(int u, int v, long long cap): u(u), v(v), cap(cap), flow(0) {}
};

struct DinicAlgorithm {
  int totalNodes;
  vector<Edge> edges;
  vector<vector<int>> adjList;
  vector<int> level, ptr;

  DinicAlgorithm(int N): totalNodes(N), edges(), adjList(N), level(N), ptr(N) {}

  void addEdge(int u, int v, long long cap) {
    if (u != v) {
      edges.emplace_back(Edge(u, v, cap));
      adjList[u].push_back(edges.size() - 1);
      edges.emplace_back(Edge(v, u, 0));
      adjList[v].push_back(edges.size() - 1);
    }
  }

  bool buildLevelGraph(int S, int T) {
    queue<int> q({S});
    fill(level.begin(), level.end(), totalNodes + 1);
    level[S] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int e_idx: adjList[u]) {
        Edge &e = edges[e_idx];
        if (e.flow < e.cap && level[e.v] > level[e.u] + 1) {
          level[e.v] = level[e.u] + 1;
          q.push(e.v);
        }
      }
    }
    return level[T] != totalNodes + 1;
  }

  long long pushFlow(int u, int T, long long flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = ptr[u]; i < (int)adjList[u].size(); ++i) {
      Edge &e = edges[adjList[u][i]];
      Edge &oe = edges[adjList[u][i]^1];
      if (level[e.v] == level[e.u] + 1) {
        long long amt = e.cap - e.flow;
        if (flow != -1 && amt > flow) amt = flow;
        long long pushed = pushFlow(e.v, T, amt);
        if (pushed > 0) {
          e.flow += pushed;
          oe.flow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  long long getMaxFlow(int S, int T) {
    long long totalFlow = 0;
    while (buildLevelGraph(S, T)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (long long flow = pushFlow(S, T))
        totalFlow += flow;
    }
    return totalFlow;
  }
};

