import java.util.*;
import java.io.*;

public class Main {
    static char[][] mazeX = new char[15][15];
    static char[][] mazeY = new char[15][15];
    static int[][][] nodeMap = new int[65][15][15];
    static int[][] maxCap = new int[15][15];
    static int[] dirX = {-1, 1, 0, 0};
    static int[] dirY = {0, 0, -1, 1};
    static int nodeCount = 1;

    static class Edge {
        int u, v;
        long cap, flow;
        public Edge() {}
        public Edge(int u, int v, long cap) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = 0;
        }
    }

    static class Dinic {
        int totalNodes;
        List<Edge> edges;
        List<List<Integer>> adjList;
        int[] level, ptr;

        public Dinic(int N) {
            totalNodes = N;
            edges = new ArrayList<>();
            adjList = new ArrayList<>();
            for (int i=0; i<N; i++) {
                adjList.add(new ArrayList<>());
            }
            level = new int[N];
            ptr = new int[N];
        }

        void addEdge(int u, int v, long cap) {
            if (u != v) {
                edges.add(new Edge(u, v, cap));
                adjList.get(u).add(edges.size() - 1);
                edges.add(new Edge(v, u, 0));
                adjList.get(v).add(edges.size() - 1);
            }
        }

        boolean buildLevelGraph(int S, int T) {
            Arrays.fill(level, totalNodes + 1);
            level[S] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(S);
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == T) break;
                for (int e_idx : adjList.get(u)) {
                    Edge e = edges.get(e_idx);
                    if (e.flow < e.cap && level[e.v] > level[e.u] + 1) {
                        level[e.v] = level[e.u] + 1;
                        q.offer(e.v);
                    }
                }
            }
            return level[T] != totalNodes + 1;
        }

        long pushFlow(int u, int T, long flow) {
            if (u == T || flow == 0) return flow;
            for (; ptr[u] < adjList.get(u).size(); ptr[u]++) {
                int e_idx = adjList.get(u).get(ptr[u]);
                Edge e = edges.get(e_idx);
                Edge oe = edges.get(e_idx ^ 1);
                if (level[e.v] == level[e.u] + 1) {
                    long amt = e.cap - e.flow;
                    if (flow != -1 && amt > flow) amt = flow;
                    long pushed = pushFlow(e.v, T, amt);
                    if (pushed > 0) {
                        e.flow += pushed;
                        oe.flow -= pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        }

        long getMaxFlow(int S, int T) {
            long totalFlow = 0;
            while (buildLevelGraph(S, T)) {
                Arrays.fill(ptr, 0);
                long flow;
                while ((flow = pushFlow(S, T, -1)) > 0) {
                    totalFlow += flow;
                }
            }
            return totalFlow;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        for (int i=1; i<=n; i++) {
            String line = br.readLine();
            for (int j=1; j<=n; j++) {
                mazeX[i][j] = line.charAt(j-1);
            }
        }

        for (int i=0; i<=t+1; i++) {
            for (int j=1; j<=n; j++) {
                for (int k=1; k<=n; k++) {
                    nodeMap[i][j][k] = nodeCount++;
                }
            }
        }
        nodeCount++;
        for (int i=1; i<=n; i++) {
            String line = br.readLine();
            for (int j=1; j<=n; j++) {
                mazeY[i][j] = line.charAt(j-1);
            }
        }

        Queue<int[]> q = new LinkedList<>();
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (mazeX[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    maxCap[i][j] = 0;
                }
            }
        }

        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int y = pos[0], x = pos[1];
            for (int i=0; i<4; i++) {
                int ny = y + dirX[i], nx = x + dirY[i];
                if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && mazeX[ny][nx] != 'Y' && maxCap[ny][nx] == -1) {
                    maxCap[ny][nx] = maxCap[y][x] + 1;
                    q.offer(new int[]{ny, nx});
                }
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (maxCap[i][j] == -1) maxCap[i][j] = (int)1e9;
                if (maxCap[i][j] > t) maxCap[i][j] = (int)1e9;
            }
        }

        int s = 0;
        int t_node = nodeCount - 1;
        Dinic flowNet = new Dinic(nodeCount);

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (mazeX[i][j] >= '1' && mazeX[i][j] <= '9') {
                    flowNet.addEdge(s, nodeMap[0][i][j], mazeX[i][j] - '0');
                }
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (mazeX[i][j] == 'Y' || mazeX[i][j] == 'Z') continue;
                for (int k=0; k<4; k++) {
                    int ny = i + dirX[k], nx = j + dirY[k];
                    if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && mazeX[ny][nx] != 'Y' && mazeX[ny][nx] != 'Z') {
                        for (int x=0; x<t; x++) {
                            if (maxCap[ny][nx] >= x+1 && maxCap[i][j] > x) {
                                flowNet.addEdge(nodeMap[x][i][j], nodeMap[x+1][ny][nx], 1000);
                            }
                        }
                    }
                }
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (mazeX[i][j] == 'Y' || mazeX[i][j] == 'Z') continue;
                for (int x=0; x<=t; x++) {
                    if (mazeY[i][j] >= '1' && mazeY[i][j] <= '9') {
                        flowNet.addEdge(nodeMap[x][i][j], nodeMap[t+1][i][j], mazeY[i][j] - '0');
                    }
                }
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (mazeX[i][j] == 'Y' || mazeX[i][j] == 'Z') continue;
                if (mazeY[i][j] >= '1' && mazeY[i][j] <= '9') {
                    flowNet.addEdge(nodeMap[t+1][i][j], t_node, mazeY[i][j] - '0');
                }
            }
        }

        System.out.println(flowNet.getMaxFlow(s, t_node));
    }
}
